130	async fn collect_chat_completion(
131	    stream: ChatEventStream,
132	    request_id: String,
133	    response_model: String,
134	    created: u64,
135	    requested_logprobs: bool,
136	    include_prompt_logprobs: bool,
137	    echo: Option<String>,
138	    return_token_ids: bool,
139	    return_tokens_as_token_ids: bool,
140	) -> Result<ChatCompletionResponse, ApiError> {
141	    let collected = stream.collect_message().await.map_err(|error| {
142	        server_error!(
143	            "failed to collect chat completion response: {}",
144	            error.to_report_string()
145	        )
146	    })?;
147	    let CollectedAssistantMessage {
148	        message,
149	        prompt_token_count,
150	        prompt_token_ids,
151	        prompt_logprobs,
152	        logprobs,
153	        token_ids,
154	        output_token_count,
155	        finish_reason,
156	        kv_transfer_params,
157	    } = collected;
158	    let stop_reason = finish_reason.as_stop_reason().map(stop_reason_to_json);
159	    let saw_tool_calls = message.tool_calls().next().is_some();
160	    let finish_reason = chat_finish_reason_to_openai(&finish_reason, saw_tool_calls)?.to_string();
161	    let tool_calls = message
162	        .tool_calls()
163	        .map(|call| ToolCall {
164	            id: call.id.clone(),
165	            tool_type: "function".to_string(),
166	            function: FunctionCallResponse {
167	                name: call.name.clone(),
168	                arguments: Some(call.arguments.clone()),
169	            },
170	        })
171	        .collect::<Vec<_>>();
172	    let logprobs = if requested_logprobs {
173	        Some(decoded_logprobs_to_openai_chat(
174	            logprobs.as_ref().ok_or_else(|| {
175	                server_error!("chat response requested logprobs but generation returned none")
176	            })?,
177	            return_tokens_as_token_ids,
178	        )?)
179	    } else {
180	        None
181	    };
182	    let prompt_logprobs = if include_prompt_logprobs {
183	        Some(decoded_prompt_logprobs_to_maps(
184	            prompt_logprobs.as_ref().ok_or_else(|| {
185	                server_error!(
186	                    "chat response requested prompt_logprobs but generation returned none"
187	                )
188	            })?,
189	            return_tokens_as_token_ids,
190	        ))
191	    } else {
192	        None
193	    };
194	    let usage = Usage::from_counts(prompt_token_count as u32, output_token_count as u32);
195	
196	    Ok(ChatCompletionResponse {
197	        id: request_id,
198	        object: "chat.completion".to_string(),
199	        created,
200	        model: response_model,
201	        choices: vec![ChatCompletionChoice {
202	            index: 0,
